{
  "schemaVersion": "0.2",
  "slug": "pagination",
  "name": "Pagination",
  "status": "experimental",
  "purpose": "Navigates across a set of pages.",
  "scenarios": [
    "Paginate search results",
    "Paginate a data table",
    "Navigate a long article"
  ],
  "props": {
    "currentPage": {
      "type": "number",
      "required": true,
      "description": "Active page (1-based)."
    },
    "totalPages": {
      "type": "number",
      "required": true,
      "description": "Total number of pages."
    },
    "onChange": {
      "type": "event",
      "required": true,
      "description": "Called when a page is selected."
    },
    "className": {
      "type": "string",
      "required": false,
      "description": "Additional CSS classes."
    }
  },
  "variants": [],
  "states": [
    {
      "name": "default",
      "description": "Pagination rendered."
    }
  ],
  "composition": {
    "allowedParents": [
      "page",
      "table",
      "card"
    ],
    "allowedChildren": [],
    "requiredContext": []
  },
  "antiPatterns": [
    "Do not use for infinite scroll.",
    "Do not hide focus indicators on page buttons."
  ],
  "a11y": {
    "role": "navigation",
    "keyboard": [
      "Tab moves through page buttons",
      "Enter selects a page"
    ],
    "focus": "Page buttons are focusable.",
    "labeling": "Labelled as Pagination.",
    "wcag": [
      "2.1.1",
      "2.4.8"
    ]
  },
  "responsive": {
    "strategy": "Horizontal list of buttons.",
    "breakpoints": {
      "compact": "Compact spacing.",
      "medium": "Normal spacing.",
      "large": "Normal spacing."
    }
  },
  "platforms": {
    "web": "supported",
    "react": "supported",
    "vue": "supported"
  },
  "rtl": {
    "supported": true,
    "strategy": "Logical CSS only; previous/next labels are reversed by content not by code.",
    "mirroredValues": []
  },
  "dataAi": {
    "role": "pagination",
    "states": [
      "default"
    ],
    "intents": [
      "navigate-pages"
    ]
  }
}

import './styles.css'

export interface PaginationProps {
  currentPage: number
  totalPages: number
  onChange: (page: number) => void
  className?: string
}

export function Pagination({ currentPage, totalPages, onChange, className }: PaginationProps) {
  const classes = ['cu-pagination', className].filter(Boolean).join(' ')
  const pages = Array.from({ length: totalPages }, (_, i) => i + 1)
  return (
    <nav aria-label="Pagination" className={classes} data-ai-role="pagination" data-ai-state="default" data-ai-intent="navigate-pages">
      <div className="cu-pagination__list">
        <button
          className="cu-pagination__button"
          disabled={currentPage <= 1}
          onClick={() => onChange(currentPage - 1)}
          type="button"
        >
          Previous
        </button>
        {pages.map((page) => (
          <button
            aria-current={page === currentPage ? 'page' : undefined}
            className={'cu-pagination__button' + (page === currentPage ? ' cu-pagination__button--current' : '')}
            key={page}
            onClick={() => onChange(page)}
            type="button"
          >
            {page}
          </button>
        ))}
        <button
          className="cu-pagination__button"
          disabled={currentPage >= totalPages}
          onClick={() => onChange(currentPage + 1)}
          type="button"
        >
          Next
        </button>
      </div>
    </nav>
  )
}

.cu-pagination {
  font-size: 0.875rem;
}

.cu-pagination__list {
  display: flex;
  align-items: center;
  gap: var(--cu-space-1);
}

.cu-pagination__button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-inline-size: 2.25rem;
  min-block-size: 2.25rem;
  padding-block: var(--cu-space-1);
  padding-inline: var(--cu-space-2);
  border: 1px solid var(--cu-color-border-default);
  border-radius: var(--cu-radius-sm);
  background: var(--cu-color-background-default);
  color: var(--cu-color-fg-default);
  font: inherit;
  cursor: pointer;
}

.cu-pagination__button:disabled {
  cursor: not-allowed;
  opacity: 0.5;
}

.cu-pagination__button--current {
  border-color: var(--cu-color-palette-brand);
  color: var(--cu-color-palette-brand);
  font-weight: 700;
}

.cu-pagination__button:focus-visible {
  outline: 3px solid var(--cu-color-palette-brand);
  outline-offset: 2px;
}
